mapper.select:
select *
from biz_medical_query_request
where company_id = #{companyId}
  and service_mode = 'DELAYED'
  and patient_name = #{patientName}
  and id_card = #{idCard}
  and process_status in ('PENDING', 'PROCESSING')
  and upload_status = 'NOT_UPLOADED'
order by id asc
limit 1

select *
from biz_medical_query_request
where company_id = #{companyId}
  and request_no = #{requestNo}
limit 1

select r.*, c.company_name
from biz_medical_query_request r
left join biz_insurance_company c on c.id = r.company_id

    r.company_id = #{companyId}
    and r.service_mode = 'DELAYED'
    and r.request_no like concat('%', #{requestNo}, '%')
    and r.patient_name like concat('%', #{patientName}, '%')
    and r.process_status = #{processStatus}
    and r.result_status = #{resultStatus}
    and r.create_time >= #{params.beginTime}
    and r.create_time <= #{params.endTime}

order by r.create_time desc, r.id desc
limit 100

select r.*, c.company_name
from biz_medical_query_request r
left join biz_insurance_company c on c.id = r.company_id

    r.company_id = #{companyId}
    and r.service_mode = 'REALTIME'
    and r.request_no like concat('%', #{requestNo}, '%')
    and r.patient_name like concat('%', #{patientName}, '%')
