    and r.result_status = #{resultStatus}
    and r.create_time >= #{params.beginTime}
    and r.create_time <= #{params.endTime}

order by r.create_time desc, r.id desc
limit 100

select r.*, c.company_name
from biz_medical_query_request r
left join biz_insurance_company c on c.id = r.company_id

    r.service_mode = 'DELAYED'
    and r.request_no like concat('%', #{requestNo}, '%')
    and c.company_name like concat('%', #{companyName}, '%')
    and r.patient_name like concat('%', #{patientName}, '%')
